    <?php include("../includes/popup_modal.php") ?>

    <script>
    (function() {
        var tabs = document.querySelectorAll('.filter-tab');
        var cards = document.querySelectorAll('.blog-card');
        var noResults = document.getElementById('blNoResults');
        var visCount = document.getElementById('blVisibleCount');
        var searchInput = document.getElementById('blSearch');
        var activeCat = 'all';
        var activeQuery = '';

        function apply() {
            var q = activeQuery.trim().toLowerCase();
            var visible = 0;
            cards.forEach(function(c) {
                var cat = c.getAttribute('data-cat');
                var title = (c.getAttribute('data-title') || '').toLowerCase();
                var catOk = (activeCat === 'all') || (cat === activeCat);
                var qOk = !q || title.indexOf(q) !== -1;
                if (catOk && qOk) { c.classList.remove('hidden'); visible++; }
                else { c.classList.add('hidden'); }
            });
            if (visCount) visCount.textContent = visible;
            if (noResults) noResults.style.display = (visible === 0) ? 'block' : 'none';
        }

        tabs.forEach(function(t) {
            t.addEventListener('click', function() {
                tabs.forEach(function(x) { x.classList.remove('active'); });
                t.classList.add('active');
                activeCat = t.getAttribute('data-cat');
                apply();
                var g = document.getElementById('blGrid');
                if (g) window.scrollTo({ top: g.offsetTop - 100, behavior: 'smooth' });
            });
        });

        // Default: All active
        if (tabs.length) tabs[0].classList.add('active');

        if (searchInput) {
            var debounce;
            searchInput.addEventListener('input', function(e) {
                clearTimeout(debounce);
                debounce = setTimeout(function() { activeQuery = e.target.value; apply(); }, 120);
            });
        }
    })();
    </script>
